function redondearADecada(a){
  if(a%1!==0 || a<0) throw "El año debe ser entero positivo";
  return a%2==0 ? Math.ceil(a/10)*10 : Math.floor(a/10)*10;
}

var multiplo_2_3 = function(n){
  if(!Number.isInteger(n)) throw "El número debe ser entero.";
  return n%3==0 ? "múltiplo de 3" : n%2==0 ? "múltiplo de 2" : "no es múltiplo de 3 o 2";
}

function esBisiesto(a){
  if(!Number.isInteger(a) || a<0) throw "El año debe ser entero positivo";
  return a%100!=0 ? a%4==0 : a%400==0;
}

var menor =(a,b,c)=>{
  return c<=a && c<=b ? c : b<=a && b<=c ? b : a;
  }

var numAEstacion= function(n) {
  if(n%1!=0 || n<0) throw "El número debe ser entero";
  let r="";
  switch(n){
    case 1: r="primavera";break;
    case 2: r="verano";break;
    case 3: r="otoño";break;
    case 4: r="invierno";break;
    default: throw "El número debe ser 1, 2, 3 o 4";
  }
  return r;
}

